INSERT INTO `product` VALUES (_binary '�^���pf��Q3pp\�','Máy định vị GNSS RTK Hi-Target V600L',NULL,NULL,NULL,'<div class=\"product-layout-rtk\" style=\"box-sizing: border-box; font-family: Arial, Helvetica, sans-serif; line-height: 1.65; color: #2d3748; max-width: 1050px; margin: 0 auto; padding: 10px;\"><!-- BANNER / TIÊU ĐỀ SẢN PHẨM -->\n<div style=\"box-sizing: border-box; background: linear-gradient(135deg, #0d47a1 0%, #1565c0 100%); color: #ffffff; padding: 24px 26px; border-radius: 8px; margin-bottom: 25px;\"><span style=\"display: inline-block; background: #00e676; color: #003311; font-size: 12px; font-weight: bold; padding: 4px 10px; border-radius: 4px; text-transform: uppercase; letter-spacing: 0.5px; margin-bottom: 8px;\">Thế Hệ Laser RTK Đột Phá</span>\n<h2 style=\"margin: 8px 0 10px 0; font-size: 22px; line-height: 1.35; color: #ffffff; font-weight: bold;\">MÁY ĐỊNH VỊ GNSS RTK HI-TARGET V600L: ĐỈNH CAO CÔNG NGHỆ LASER &amp; AR STAKEOUT THỰC ĐỊA</h2>\n<p style=\"margin: 0; font-size: 14.5px; opacity: 0.95; line-height: 1.6;\">Bạn thường xuyên gặp thách thức khi đo đạc tại các khu vực nguy hiểm, rãnh hào sâu, vách dựng đứng hay dưới gầm cầu bị che khuất sóng vệ tinh? <strong>Hi-Target V600L</strong> kết hợp đồng thời <strong>bo mạch 1.760 kênh, bù nghiêng IMU không cần khởi tạo, Camera kép AR và tia Laser xanh cải tiến</strong>. Giải pháp đo lường không tiếp xúc an toàn tuyệt đối, định vị cọc tim trực quan trên hình ảnh thực tế và chuẩn xác đến từng milimet.</p>\n</div>\n<!-- BLOCK 1: ẢNH TRÁI - ĐẶC ĐIỂM VƯỢT TRỘI PHẢI -->\n<div style=\"box-sizing: border-box; display: flex; flex-wrap: wrap; gap: 24px; align-items: flex-start; margin-bottom: 30px; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 18px;\">\n<div style=\"box-sizing: border-box; flex: 1 1 340px; max-width: 100%; text-align: center;\"><img style=\"display: block; width: 100%; max-width: 400px; height: auto; margin: 0 auto; border-radius: 8px; border: 1px solid #edf2f7; box-shadow: 0 4px 10px rgba(0,0,0,0.05);\" src=\"https://bizweb.dktcdn.net/100/498/687/files/hi-target-v600l.jpg?v=1789636837403\" alt=\"Máy định vị GNSS RTK Hi-Target V600L chính hãng\" loading=\"lazy\">\n<p style=\"margin: 8px 0 0 0; font-size: 13px; color: #718096; font-style: italic;\">Đầu thu GNSS RTK Hi-Target V600L tích hợp cụm Laser xanh &amp; Camera kép</p>\n</div>\n<div style=\"box-sizing: border-box; flex: 2 1 420px; min-width: 280px;\">\n<h3 style=\"color: #0d47a1; font-size: 19px; border-left: 5px solid #00e676; padding-left: 12px; margin: 0 0 16px 0; font-weight: bold;\">Đặc Điểm Vượt Trội Của Hi-Target V600L</h3>\n<div style=\"box-sizing: border-box; display: flex; flex-wrap: wrap; gap: 12px;\">\n<div style=\"box-sizing: border-box; flex: 1 1 calc(50% - 6px); min-width: 230px; border: 1px solid #e2e8f0; border-radius: 6px; padding: 12px; background-color: #f8fafc;\">\n<h4 style=\"margin: 0 0 6px 0; color: #0d47a1; font-size: 14.5px; font-weight: bold;\">? Đo Laser Xanh Không Tiếp Xúc</h4>\n<p style=\"margin: 0; font-size: 13px; color: #4a5568; line-height: 1.5;\">Laser xanh cường độ cao kết hợp camera ngắm mục tiêu trực quan. Đo chuẩn xác các điểm che khuất với sai số chỉ <strong>2 cm trong phạm vi 5m – 10m</strong> ngay cả khi mất tín hiệu GNSS.</p>\n</div>\n<div style=\"box-sizing: border-box; flex: 1 1 calc(50% - 6px); min-width: 230px; border: 1px solid #e2e8f0; border-radius: 6px; padding: 12px; background-color: #f8fafc;\">\n<h4 style=\"margin: 0 0 6px 0; color: #0d47a1; font-size: 14.5px; font-weight: bold;\">? Bù Nghiêng IMU 60° Tức Thì</h4>\n<p style=\"margin: 0; font-size: 13px; color: #4a5568; line-height: 1.5;\">Cảm biến IMU 200 Hz thế hệ mới không cần khởi tạo hay lắc sào cân bọt thủy. Bật máy là đo ngay, tăng năng suất thực địa lên tới <strong>40%</strong>.</p>\n</div>\n<div style=\"box-sizing: border-box; flex: 1 1 calc(50% - 6px); min-width: 230px; border: 1px solid #e2e8f0; border-radius: 6px; padding: 12px; background-color: #f8fafc;\">\n<h4 style=\"margin: 0 0 6px 0; color: #0d47a1; font-size: 14.5px; font-weight: bold;\">? Camera Kép – Bố Trí AR Thực Cảnh</h4>\n<p style=\"margin: 0; font-size: 13px; color: #4a5568; line-height: 1.5;\">Camera trước hỗ trợ ngắm laser, camera đáy định vị cọc tim trực tiếp trên bản vẽ CAD (DWG/DXF) và hình ảnh thực địa, tăng hiệu suất cắm mốc lên <strong>50%</strong>.</p>\n</div>\n<div style=\"box-sizing: border-box; flex: 1 1 calc(50% - 6px); min-width: 230px; border: 1px solid #e2e8f0; border-radius: 6px; padding: 12px; background-color: #f8fafc;\">\n<h4 style=\"margin: 0 0 6px 0; color: #0d47a1; font-size: 14.5px; font-weight: bold;\">?️ Bo Mạch 1.760 Kênh Siêu Tốc</h4>\n<p style=\"margin: 0; font-size: 13px; color: #4a5568; line-height: 1.5;\">Theo dõi đầy đủ các chòm sao GPS, BDS, GLONASS, GALILEO, QZSS, NavIC, SBAS và dịch vụ định vị điểm chính xác PPP (B2b-PPP, Galileo E6-HAS).</p>\n</div>\n<div style=\"box-sizing: border-box; flex: 1 1 calc(50% - 6px); min-width: 230px; border: 1px solid #e2e8f0; border-radius: 6px; padding: 12px; background-color: #f8fafc;\">\n<h4 style=\"margin: 0 0 6px 0; color: #0d47a1; font-size: 14.5px; font-weight: bold;\">? Radio LoRa Tầm Xa 15 – 20 km</h4>\n<p style=\"margin: 0; font-size: 13px; color: #4a5568; line-height: 1.5;\">Công suất phát tùy chỉnh 1W / 1.5W với 116 kênh, tương thích đa giao thức (LoRa, Trimtalk450S, Satel-3AS...), đo trạm Base – Rover cự ly cực xa.</p>\n</div>\n<div style=\"box-sizing: border-box; flex: 1 1 calc(50% - 6px); min-width: 230px; border: 1px solid #e2e8f0; border-radius: 6px; padding: 12px; background-color: #f8fafc;\">\n<h4 style=\"margin: 0 0 6px 0; color: #0d47a1; font-size: 14.5px; font-weight: bold;\">?️ Siêu Nhẹ 0.73kg – Chuẩn Bền IP68</h4>\n<p style=\"margin: 0; font-size: 13px; color: #4a5568; line-height: 1.5;\">Vỏ hợp kim magie chuẩn quân sự <strong>MIL-STD-810G</strong>, chịu rơi 1.8 m xuống nền bê tông. Pin hoạt động 20 giờ, hỗ trợ sạc nhanh Type-C.</p>\n</div>\n</div>\n</div>\n</div>\n<!-- BLOCK 2: ẢNH TRÁI - ỨNG DỤNG THỰC TẾ PHẢI -->\n<div style=\"box-sizing: border-box; display: flex; flex-wrap: wrap; gap: 24px; align-items: center; margin-bottom: 30px; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 18px;\">\n<div style=\"box-sizing: border-box; flex: 1 1 340px; max-width: 100%; text-align: center;\"><img style=\"display: block; width: 100%; max-width: 400px; height: auto; margin: 0 auto; border-radius: 8px; border: 1px solid #edf2f7; box-shadow: 0 4px 10px rgba(0,0,0,0.05);\" src=\"https://bizweb.dktcdn.net/100/498/687/files/hi-target-v600-8.png?v=1789636837307\" alt=\"Ứng dụng đo đạc khảo sát thực địa Hi-Target V600L\" loading=\"lazy\">\n<p style=\"margin: 8px 0 0 0; font-size: 13px; color: #718096; font-style: italic;\">Đo vẽ khảo sát địa hình hiểm trở và cắm mốc công trình giao thông</p>\n</div>\n<div style=\"box-sizing: border-box; flex: 2 1 420px; min-width: 280px;\">\n<h3 style=\"color: #0d47a1; font-size: 19px; border-left: 5px solid #00e676; padding-left: 12px; margin: 0 0 16px 0; font-weight: bold;\">Ứng Dụng Thực Tế Trong Công Tác Khảo Sát</h3>\n<ul style=\"padding-left: 18px; margin: 0; font-size: 14px; line-height: 1.8;\">\n<li style=\"margin-bottom: 8px;\"><strong>Khảo sát địa hình hiểm trở &amp; vị trí che khuất:</strong> Dùng tia laser bắt tọa độ dưới gầm cầu, khe hẹp, mương rãnh thoát nước, ranh đất có tường rào kiên cố không thể áp sào trực tiếp.</li>\n<li style=\"margin-bottom: 8px;\"><strong>Thi công xây dựng công trình &amp; giao thông:</strong> Bố trí tim trục, cọc móng, định vị ranh mốc giải phóng mặt bằng (GPMB) trực quan bằng hình ảnh AR kết hợp nạp trực tiếp bản vẽ CAD.</li>\n<li style=\"margin-bottom: 8px;\"><strong>Đo đạc địa chính &amp; thành lập bản đồ:</strong> Đo vẽ chi tiết ranh giới thửa đất, góc khuất chân tường nhà, mép taluy dốc đứng với công nghệ bù nghiêng IMU 60° mà không cần bọt thủy sào phải chuẩn tâm.</li>\n<li style=\"margin-bottom: 0;\"><strong>Khai thác khoáng sản &amp; thủy lợi:</strong> Đo cao độ mặt nước, mép moong khai thác mỏ hoặc thân đập từ khoảng cách xa, đảm bảo an toàn tuyệt đối cho kỹ sư khảo sát.</li>\n</ul>\n</div>\n</div>\n<!-- BLOCK 3: BẢNG THÔNG SỐ KỸ THUẬT KÈM ẢNH MINH HỌA BÊN TRÁI -->\n<div style=\"box-sizing: border-box; margin-bottom: 30px; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 18px;\">\n<h3 style=\"color: #0d47a1; font-size: 19px; border-left: 5px solid #00e676; padding-left: 12px; margin: 0 0 16px 0; font-weight: bold;\">Bảng Thông Số Kỹ Thuật Chi Tiết Hi-Target V600L</h3>\n<div style=\"box-sizing: border-box; display: flex; flex-wrap: wrap; gap: 20px; align-items: flex-start;\">\n<div style=\"box-sizing: border-box; flex: 1 1 300px; text-align: center;\"><img style=\"display: block; width: 100%; max-width: 360px; height: auto; margin: 0 auto; border-radius: 8px; border: 1px solid #e2e8f0;\" src=\"https://bizweb.dktcdn.net/100/498/687/files/rtk-hi-target-v600l-2.jpg?v=1789636837347\" alt=\"Cấu tạo chi tiết máy GNSS RTK V600L\" loading=\"lazy\">\n<p style=\"margin: 8px 0 0 0; font-size: 13px; color: #718096; font-style: italic;\">Hệ thống cảm biến và giao diện kết nối trên Hi-Target V600L</p>\n</div>\n<div style=\"box-sizing: border-box; flex: 2 1 440px; overflow-x: auto;\">\n<table style=\"width: 100%; border-collapse: collapse; font-size: 13px; text-align: left; background-color: #ffffff;\">\n<thead>\n<tr style=\"background-color: #0d47a1; color: #ffffff;\">\n<th style=\"padding: 9px 12px; border: 1px solid #cbd5e1; width: 34%;\">Hạng mục</th>\n<th style=\"padding: 9px 12px; border: 1px solid #cbd5e1;\">Thông số kỹ thuật</th>\n</tr>\n</thead>\n<tbody>\n<tr style=\"background-color: #f1f5f9;\">\n<td style=\"padding: 7px 12px; font-weight: bold; border: 1px solid #cbd5e1; color: #0d47a1;\" colspan=\"2\">1. Theo dõi vệ tinh GNSS</td>\n</tr>\n<tr>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1; font-weight: bold;\">Số kênh theo dõi</td>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1;\">1.760 kênh</td>\n</tr>\n<tr>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1; font-weight: bold;\">Tín hiệu vệ tinh</td>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1;\">GPS, BDS, GLONASS, GALILEO, QZSS, NavIC, SBAS, B2b-PPP, Galileo E6-HAS</td>\n</tr>\n<tr style=\"background-color: #f1f5f9;\">\n<td style=\"padding: 7px 12px; font-weight: bold; border: 1px solid #cbd5e1; color: #0d47a1;\" colspan=\"2\">2. Độ chính xác định vị</td>\n</tr>\n<tr>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1; font-weight: bold;\">Động thời gian thực (RTK)</td>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1;\">Ngang (H): 8 mm + 1 ppm | Dọc (V): 15 mm + 1 ppm RMS (Fix &lt; 10s)</td>\n</tr>\n<tr>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1; font-weight: bold;\">Đo Laser không tiếp xúc</td>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1;\">2 cm (trong 5m) | 3 cm (trong 10m); Tầm laser 30m</td>\n</tr>\n<tr>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1; font-weight: bold;\">Bù nghiêng IMU</td>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1;\">Tần số 200 Hz; Góc nghiêng 0° ~ 60° không cần khởi tạo</td>\n</tr>\n<tr>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1; font-weight: bold;\">Độ chính xác cắm mốc AR</td>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1;\">2 cm</td>\n</tr>\n<tr style=\"background-color: #f1f5f9;\">\n<td style=\"padding: 7px 12px; font-weight: bold; border: 1px solid #cbd5e1; color: #0d47a1;\" colspan=\"2\">3. Phần cứng &amp; Môi trường</td>\n</tr>\n<tr>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1; font-weight: bold;\">Kích thước / Cân nặng</td>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1;\">130.97 mm × 68.7 mm / ≤ 0.73 kg (Vỏ hợp kim magie)</td>\n</tr>\n<tr>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1; font-weight: bold;\">Hệ thống Camera</td>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1;\">Camera trước (ngắm laser) + Camera dưới (bố trí điểm AR cảnh thực)</td>\n</tr>\n<tr>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1; font-weight: bold;\">Chuẩn bảo vệ &amp; Va đập</td>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1;\">IP68 (ngâm nước 1m), MIL-STD-810G, chịu rơi tự do 1.8 m xuống bê tông</td>\n</tr>\n<tr>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1; font-weight: bold;\">Thời lượng Pin &amp; Bộ nhớ</td>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1;\">Pin dùng 20 giờ (Rover UHF/GSM), sạc Type-C 5V/2.8A | ROM trong 64 GB</td>\n</tr>\n<tr>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1; font-weight: bold;\">Radio LoRa &amp; Kết nối</td>\n<td style=\"padding: 7px 12px; border: 1px solid #cbd5e1;\">410–470 MHz (116 kênh, 1W/1.5W, cự ly 15–20km), 4G, Wi-Fi ax, BT 5.2, NFC</td>\n</tr>\n</tbody>\n</table>\n</div>\n</div>\n</div>\n<!-- BLOCK 4: TRỌN BỘ SẢN PHẨM KÈM HÌNH ẢNH MINH HỌA -->\n<div style=\"box-sizing: border-box; background-color: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 20px; margin-bottom: 30px;\">\n<h3 style=\"color: #0d47a1; font-size: 19px; border-left: 5px solid #00e676; padding-left: 12px; margin: 0 0 16px 0; font-weight: bold;\">Trọn Bộ Rover Hi-Target V600L Tiêu Chuẩn Gồm Có</h3>\n<div style=\"box-sizing: border-box; display: flex; flex-wrap: wrap; gap: 20px; align-items: center;\">\n<div style=\"box-sizing: border-box; flex: 1 1 340px;\">\n<ol style=\"margin: 0; padding-left: 20px; font-size: 14px; line-height: 1.85;\">\n<li>01 Máy thu GNSS Hi-Target V600L chính hãng.</li>\n<li>01 Sổ tay điều khiển chuyên dụng iHand 55 (Android 11, Pin khủng 9.200 mAh).</li>\n<li>01 Phần mềm khảo sát bản quyền Hi-Survey Road (CAD DXF/DWG, AR Stakeout).</li>\n<li>01 Bộ nạp nguồn sạc kép cho V600L + iHand 55 kèm cáp Type-C.</li>\n<li>01 Anten Radio UHF độ nhạy cao.</li>\n<li>01 Gá kẹp sổ tay gắn sào có tích hợp địa bàn cân bằng.</li>\n<li>01 Sào Cacbon chuyên dụng kèm bao đựng sào.</li>\n<li>01 Vali chống sốc chịu lực đựng trọn bộ thiết bị.</li>\n</ol>\n</div>\n<div style=\"box-sizing: border-box; flex: 1 1 340px; display: flex; flex-direction: column; gap: 10px; text-align: center;\"><img style=\"display: block; width: 100%; max-width: 420px; height: auto; margin: 0 auto; border-radius: 6px; border: 1px solid #e2e8f0;\" src=\"https://bizweb.dktcdn.net/100/498/687/files/rtk-hi-target-v600l.jpg?v=1789636837367\" alt=\"Trọn bộ phụ kiện máy RTK Hi-Target V600L\" loading=\"lazy\"> <img style=\"display: block; width: 100%; max-width: 420px; height: auto; margin: 0 auto; border-radius: 6px; border: 1px solid #e2e8f0;\" src=\"https://bizweb.dktcdn.net/100/498/687/files/camera-hi-target-v600l.jpg?v=1789636837387\" alt=\"Cụm camera AR phía dưới của Hi-Target V600L\" loading=\"lazy\"></div>\n</div>\n</div>\n<!-- BLOCK 5: VIDEO THỰC NGHIỆM ĐỒNG BỘ TỈ LỆ 9:16 (SHORTS) -->\n<div style=\"box-sizing: border-box; margin-bottom: 30px;\">\n<h3 style=\"color: #0d47a1; font-size: 19px; border-left: 5px solid #00e676; padding-left: 12px; margin: 0 0 8px 0; font-weight: bold;\">Video Thực Nghiệm Thực Tế Hi-Target V600L</h3>\n<p style=\"margin: 0 0 16px 0; font-size: 14px; color: #4a5568;\">Theo dõi video trải nghiệm thực tế từ mở hộp sản phẩm đến các bài kiểm tra độ bền va đập và khả năng chống chịu nước chuẩn IP68:</p>\n<!-- LƯỚI 3 VIDEO DỌC TỰ CO GIÃN THEO SAPO -->\n<div style=\"box-sizing: border-box; display: flex; flex-wrap: wrap; gap: 16px; justify-content: center;\"><!-- Video 1: Review trọn bộ -->\n<div style=\"box-sizing: border-box; flex: 1 1 280px; max-width: 320px; background: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 12px; box-shadow: 0 2px 6px rgba(0,0,0,0.04);\">\n<div style=\"margin: 0 0 8px 0; font-size: 14px; font-weight: bold; color: #1e3a8a; text-align: center; min-height: 38px; display: flex; align-items: center; justify-content: center;\">? Review Trọn Bộ Máy V600L</div>\n<div sty